arguments.command:
cd /tmp/symbols

# Use -i for inlined functions and -p for prettier output
# Also try with the full binary + debug to get better results for data labels
echo "=== Thread 7046 (SGen worker) - trying with inlines ==="
for addr in 0x2f4b20 0x2f4c84; do
    echo "  $addr:"
    addr2line -f -i -e libmonosgen-2.0.so.dbg "$addr" 2>/dev/null
    echo ""
done

echo "=== Using nm on debug file for SGen worker addresses ==="
# Find the actual function containing those addresses
nm libmonosgen-2.0.so.dbg 2>/dev/null | sort | awk '
/^[0-9a-f]+ [tT]/ { syms[NR] = $0; addrs[NR] = strtonum("0x"$1); names[NR] = $3; count=NR }
END {
    targets[1] = 0x2f4b20
    targets[2] = 0x2f4c84
    targets[3] = 0x2c1a40
    for (t=1; t<=3; t++) {
        best = ""
        best_addr = 0
        for (i=1; i<=count; i++) {
            if (addrs[i] <= targets[t] && addrs[i] > best_addr) {
                best_addr = addrs[i]
                best = names[i]
            }
        }
        printf "0x%x -> %s+0x%x\n", targets[t], best, targets[t] - best_addr
    }
}
'

